using System.Collections.Generic;

namespace Iryo.Pharmacy;

public class Logger
{
	private readonly List<string> _lines = new List<string>();

	public IReadOnlyList<string> Lines => _lines;

	public void Log(string message)
	{
		_lines.Add("[調剤] " + message);
	}
}

